-- ============================================================================
--  AI prompts seed — prompt_type 4 tool: one row per model-callable
--  tool, its DESCRIPTION as DB-editable text.
--  Table: llm.ai_prompts (DDL + the shared contract: 06_ai_prompts.sql;
--  sibling static files 01..09 — one per prompt category).
--
--  The deep agent's tool schemas lived only in the Python tool classes
--  (llm_agents/deep_agents/tools — the Tool subclasses'
--  DEFAULT_DESCRIPTION constants); this seed migrates the descriptions
--  into llm.ai_prompts so they are editable without a code change.
--  Resolution at run start (runner.run_thread -> fetch_tool_prompts,
--  applied by the tool kits at mount time — tools.base's override
--  contract): the ACTIVE row's instruction (joined by
--  prompt_key|prompt_sub_type — a tool's db_key) wins; a missing key,
--  a deactivated row, or a DB outage falls back to the built-in
--  constant — fail-soft, a run never dies over prompt management.
--
--  prompt_sub_type groups the rows by the tool's kit/domain (an
--  open-ended TEXT vocabulary, no label_dim mirror): sandbox = the
--  docker py-sandbox tools, delegation = the loop's spawn/collect,
--  plan_main / plan_spawn = the plan-mutation tools' MAIN / spawn
--  variants (the SAME tool name carries two authority-narrowed
--  schemas), plan = the thread-internal search, stats = the stats_*
--  study tools, mcp = the read-only DB
--  MCP server's tools (CATALOG rows only — the MCP server owns those
--  live schemas; the rows document them in this registry).
--
--  SEEDED FROM the tool classes (dollar-quoted $txt$ blocks — no
--  escaping): tools.sandbox_tools / tools.delegation_tools /
--  tools.plan_tools / tools.thread_search / tools.stats_tools /
--  tools.prompt_tools / tools.kg_tools DEFAULT_DESCRIPTION constants,
--  plus llm_agents/mcp/readonly_server.py's tool docstrings for the
--  mcp rows. Keep the seed and the constants in sync —
--  temp_scripts/check_tool_prompts.py asserts it.
--
--  Idempotent — re-running refreshes the seeded texts in place. The
--  version column stays at its seeded 1 and is deliberately NOT in the
--  ON CONFLICT SET: a re-run never resets a manually bumped version
--  (the UI edit path bumps it).
-- ============================================================================

INSERT INTO llm.ai_prompts (prompt_key, prompt_sub_type, prompt_type, title, version, instruction, preview, note, ordinal) VALUES
    ('sandbox_write_file',
     'sandbox',
     4,
     'Tool: sandbox_write_file',
     1,
     $txt$Write a text file into your private sandbox scratch directory (paths are sandbox-relative, e.g. 'scripts/study.py' or 'data/dates.csv'; no '..'; UTF-8, 512 KB cap). The session workspace is minted with the standard layout: scripts/ for your .py files, data/ for fetched or intermediate files, outputs/ for final results, figures/ for plots — put each file in its lane. Use the tool for the scripts you will run with sandbox_run and for the data files those scripts consume. Scripts execute top-level — ONE failing query aborts the whole run — so structure study scripts with a try/except per query block that records the error and continues; when a run then fails, patch the one broken block with sandbox_edit_file instead of rewriting the file here.$txt$,
     'Write a text file into the private sandbox scratch directory.',
     'Schema description the model sees; tools.sandbox_tools.SandboxWriteFileTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     1),
    ('sandbox_run',
     'sandbox',
     4,
     'Tool: sandbox_run',
     1,
     $txt$Execute one .py file you previously wrote into the sandbox, inside the docker py-sandbox (py3.12 + pandas/numpy/scipy/scikit-learn/statsmodels/polars/pyarrow/duckdb); the script's working directory IS the sandbox directory. Returns JSON {script, exit_code, timed_out, duration_s, db, stdout, stderr} with output capped. The environment is a minimal passthrough plus the READ-ONLY database credentials: PGHOST / PGPORT / PGDATABASE / PGUSER / PGPASSWORD point at the readonly_analytics role, so `psycopg.connect()` connects with SELECT-only rights and DB writes fail. Sibling files in the sandbox are importable; relative paths the script writes land inside the sandbox. MATCH FIRST — before writing any calculation function, check what already exists: the finished study_kit package is importable everywhere (`import study_kit`). study_kit.db.query(sql) / fetch_daily_bars(sec_type, code, start, end) for read-only DB queries and daily bars; study_kit.db.fetch_spread_stats(sec_type, code) retrieves the MATERIALIZED MA-spread trailing stats (the 9 price_vs_ma*/ma5_vs_ma* gaps' value + trailing-252d pct_rank / zscore / stretched verdict, from analysis.mov_ave_spreads_detail joined to analysis.mov_ave_spreads_detail_trailing — retrieve, never recompute); study_kit.db.fetch_amt_metrics(sec_type, code) retrieves the MATERIALIZED trading-amount metrics (amt MAs, their Bollinger σ, market share, slopes — the 量能 lane, analysis.mov_ave_trading_amt; etf/stock/industry only); study_kit.studies (sma, ema, wilder_rsi, macd, kdj, bollinger, roc, zscore, trailing_pct_rank, drawdown, forward_return, forward_blend, ma_alignment, volume_contrast, spread_report) for the rest. When a needed calculation matches an existing function or materialized column, import and call it AS-IS in the script rather than adding a new function — write new code only for what the kit and the tables lack.$txt$,
     'Execute one written .py script inside the docker py-sandbox.',
     'Schema description the model sees; tools.sandbox_tools.SandboxRunTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     2),
    ('sandbox_read_file',
     'sandbox',
     4,
     'Tool: sandbox_read_file',
     1,
     $txt$Read one file back out of the sandbox directory (the files a script wrote, logs, …) as UTF-8 text; files beyond max_bytes return head+tail with a truncation marker. Paths are sandbox-relative.$txt$,
     'Read one file back out of the sandbox directory.',
     'Schema description the model sees; tools.sandbox_tools.SandboxReadFileTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     3),
    ('sandbox_list_files',
     'sandbox',
     4,
     'Tool: sandbox_list_files',
     1,
     $txt$List every file currently in the sandbox directory — JSON array of {path, bytes, modified}, sorted by path.$txt$,
     'List the sandbox scratch directory.',
     'Schema description the model sees; tools.sandbox_tools.SandboxListFilesTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     4),
    ('sandbox_edit_file',
     'sandbox',
     4,
     'Tool: sandbox_edit_file',
     1,
     $txt$Patch an existing sandbox file in place — replace an exact old_text block with new_text (path sandbox-relative). The tool reads the file, replaces every verified occurrence (default: exactly one; pass expected_count for a repeated block) and writes the file back — a one-block fix costs a hundred bytes instead of rewriting the whole file with sandbox_write_file. old_text must match the file byte-for-byte (indentation included): sandbox_read_file the file first when you did not write it this session. When a sandbox_run fails, patch the ONE broken block with this tool and re-run — never resend the whole file per fix.$txt$,
     'Patch one exact block of an existing sandbox file in place.',
     'Schema description the model sees; tools.sandbox_tools.SandboxEditFileTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     5),
    ('spawn_subagent',
     'delegation',
     4,
     'Tool: spawn_subagent',
     1,
     $txt$Spawn a subagent that pursues ONE self-contained business sub-question with the same MCP tools (read-only DB queries plus the web_search / web_summarize live web tools) and returns its final answer. The subagent does not see this conversation — it receives the goal you write, phrased as the business question it settles (the subject + the metric/aspect to study), with every schema/table/column hint it needs; when the host attaches a run context, the subagent also sees that (subject, focus question, selected prompts), so the goal states THIS spawn's question. Its final answer comes back as this tool's result (or via collect_subagents for a background spawn) — read it before concluding. A subagent may itself spawn further subagents when its investigation needs it, up to the spawn-depth cap (the tool is absent at the cap). The spawner supervises every subagent (concurrency cap and timeout); spawn failures and timeouts come back as this tool's result. When your work splits into NON-OVERLAPPING sub-questions, issue several spawn_subagent calls in ONE step — sibling calls run in parallel, while one-at-a-time spawns serialize the work. With background=true the call returns immediately with the run id and the subagent runs in parallel while you keep working — gather its result later with collect_subagents, and note its run id so a plan update can stop it if the plan changes.$txt$,
     'Delegate one self-contained sub-question to a supervised subagent.',
     'Schema description the model sees; tools.delegation_tools.SpawnSubagentTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     5),
    ('collect_subagents',
     'delegation',
     4,
     'Tool: collect_subagents',
     1,
     $txt$Gather the results of background subagents (spawned with background=true). Reports each requested spawn's finished answer or its still-running status; with wait=true (the default) it blocks until the requested spawns finish (up to timeout seconds) before reporting. Call it before your final answer — an uncollected spawn blocks the answer. Call it with no arguments to collect every outstanding spawn.$txt$,
     'Gather the results of background spawns.',
     'Schema description the model sees; tools.delegation_tools.CollectSubagentsTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     6),
    ('update_plan',
     'plan_main',
     4,
     'Tool: update_plan (main lane)',
     1,
     $txt$Rework the plan's NOT-YET-STARTED part when your findings change what remains to be done: add steps (optionally delegated spawns with a self-contained goal), revise or remove pending steps, and terminate running background subagents when the plan changed fundamentally. Steps already in_progress/completed/failed are history — they never move. The result carries the current rendered plan.$txt$,
     'Rework the not-yet-run part of the plan (main lane authority).',
     'Schema description the model sees; tools.plan_tools.UpdatePlanTool.DEFAULT_DESCRIPTION is the built-in fallback. The spawn variant of the same tool name is the plan_spawn row.',
     7),
    ('update_plan',
     'plan_spawn',
     4,
     'Tool: update_plan (spawn)',
     1,
     $txt$Extend YOUR OWN spawned path when your work hits something that needs further investigation: add_nodes appends investigation nodes under your spawn, each node ONE smaller goal of your spawn's goal (you then work each node and tick it completed with update_plan_step only when its goal is settled). You cannot touch any other node, step, or agent.$txt$,
     'Extend the spawn''s own path with investigation nodes.',
     'Schema description the model sees; tools.plan_tools.SubUpdatePlanTool.DEFAULT_DESCRIPTION is the built-in fallback. The main-lane variant of the same tool name is the plan_main row.',
     8),
    ('update_plan_step',
     'plan_spawn',
     4,
     'Tool: update_plan_step',
     1,
     $txt$Tick one of YOUR OWN spawn's investigation nodes by the state id its update_plan call reported: 'in_progress' when you start it, 'completed' only when the node's goal is settled (the tick marks that goal finished) or 'failed' when it cannot be — plus a one-line note recording what settled or why it failed. CRITICAL is a MUST CHECK on every completed tick: pass critical=true when the note records a critical discovery — a finding that changes the run's conclusion (a material break in the evidence, a risk/trigger the plan must react to, a number that overturns the working view); flagged notes surface as CRITICAL in search_thread_context and weigh on the reviews and the final answer. You cannot tick any other node.$txt$,
     'Tick one of the spawn''s own nodes by state id.',
     'Schema description the model sees; tools.plan_tools.UpdatePlanStepTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     9),
    ('search_thread_context',
     'plan',
     4,
     'Tool: search_thread_context',
     1,
     $txt$Keyword-search the WHOLE RUN's recorded LLM work across its CHAIN OF GRAPHS — one run = three chained LangGraphs (plan → custom → result, one thread each), and this tool spans every thread of the run over TWO full-text lanes: the recorded REQUESTS (what was ASKED, ANSWERED or FETCHED anywhere in the run — the planner's proposal, each step and spawn, the reviews and the final answer) and the recorded CONTEXT PAYLOADS themselves (the plan JSON, step directives and result notes, spawn answers, the graphs' syntheses — matched over their GIN-indexed tags). Words are AND-ed; Chinese is segmented automatically — natural keywords work, no operators needed. Request hits show the request id, the GRAPH and node/step each belongs to ([plan|node] / [custom|node] / [result|node]) and snippets of the matched input and output; context hits show ctx#<id> with the payload's kind label and snippet; the result header lists each graph's full thread id. CRITICAL DISCOVERIES are a MUST CHECK before you conclude: context rows the earlier agents flagged as findings that change the run's conclusion render with a CRITICAL mark — call with critical_only=true (query optional) to list them alone, and weigh every one in your own reply. HOW TO READ A FULL CONTEXT: search first to locate the row, then fetch the exact persisted payload with db_run_query over the context table — SELECT c.node, l.label AS kind, c.payload FROM llm.deep_agent_contexts c JOIN static.label_dim l ON l.domain = 'agent_context_kind' AND l.code = c.kind WHERE c.thread_id = '<the graph's thread id from the header>' (kind labels: plan = the plan JSON, step-input/step-result = a step's directive/result note, graph-output = the custom graph's synthesis, final-result = the run's answer). USE IT before redoing work an earlier graph, step or spawn may already have finished (a fetched table, a computed number, a concluded judgment), and when your node needs evidence or the plan contract an earlier graph's conversation saw.$txt$,
     'Keyword-search this run''s own recorded LLM work (requests + context payloads).',
     'Schema description the model sees; tools.thread_search.ThreadSearchTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     10),
    ('db_run_query',
     'mcp',
     4,
     'Tool: db_run_query (MCP)',
     1,
     $txt$Execute ONE read-only SQL statement (SELECT / WITH / EXPLAIN / SHOW / TABLE / VALUES) and return {"columns", "rows", "metadata"}. metadata carries row_count, truncated, data_size_bytes, and the head/tail 5 rows. Params are positional, matched to $1/$2/... Use the schema-qualified table name (e.g. stats.sec_info). RETRIEVE SMALL, AGGREGATE DOWNSTREAM: prefer several SMALL statements — one narrow SELECT per fetch (just the needed columns, filtered on the table's key grain) — then aggregate/derive in pandas or a follow-up small query. A multi-CTE monolith (joins + window functions + percentiles in one statement) fails as a whole and burns a full round per bug; iterate small and check each result's shape before building on it.$txt$,
     'One read-only SQL statement against the database.',
     'CATALOG row — the MCP server (llm_agents/mcp/readonly_server.py) owns the live schema; this row documents it in the registry.',
     11),
    ('db_list_tables',
     'mcp',
     4,
     'Tool: db_list_tables (MCP)',
     1,
     $txt$List tables / views in one schema with approximate row counts, so queries can target the right table before writing SQL. Returns a JSON array of {"table", "kind", "approx_rows"}.$txt$,
     'List one schema''s tables with row counts.',
     'CATALOG row — the MCP server (llm_agents/mcp/readonly_server.py) owns the live schema; this row documents it in the registry.',
     12),
    ('db_describe_table',
     'mcp',
     4,
     'Tool: db_describe_table (MCP)',
     1,
     $txt$Describe one table: column names, data types, nullability and primary-key membership. Returns a JSON array of {"column", "type", "not_null", "primary_key"}.$txt$,
     'Describe one table''s columns.',
     'CATALOG row — the MCP server (llm_agents/mcp/readonly_server.py) owns the live schema; this row documents it in the registry.',
     13),
    ('text_search',
     'mcp',
     4,
     'Tool: text_search (MCP)',
     1,
     $txt$Weighted FULL-TEXT search over the text schema's GIN-indexed search_tsv columns (Chinese is segmented automatically — raw Chinese text in a plain db_run_query ILIKE/tsquery will NOT match). Ranks by ts_rank, best first; when EVERY query word is overly common (text.search_lexicon_df >= 25%-DF lexemes) it orders by the article date instead (rank stays a returned column + tiebreak) — see the "ordered_by" field. order_by picks the ranking: "rank" (default — the relevance strategy above), "date" (newest first), "votes" (thumbs-up count DESC — news articles / news comments) or "comments" (most-discussed DESC, news only — the comment count rides back as n_comments). Returns {"query", "table", "search_tokens", "ordered_by", "row_count", "truncated", "hits": [{columns + rank + snippet}]}. query: free text; words are AND-ed (websearch syntax). table: news, news_comments, news_digestions, llm_qa, llm_qa_by_ask, llm_qa_by_research. Optional scalar filters — only the ones the table supports are accepted: industry_id / sector_id / source / author, code, news_id, date_from / date_to (inclusive). order_by — rank | date | votes | comments per the table's support (votes: news, news_comments; comments: news); an unsupported combination errors listing what the table supports.$txt$,
     'Weighted full-text search over the text-schema corpus (Chinese segmented), orderable by rank, date, thumbs-up votes or comment count.',
     'CATALOG row — the MCP server (llm_agents/mcp/readonly_server.py) owns the live schema; this row documents it in the registry.',
     14),
    ('web_search',
     'mcp',
     4,
     'Tool: web_search (MCP)',
     1,
     $txt$Search the open web (LIVE network call, no DB) and return the normalized references WITHOUT summarizing: {"provider", "engine", "request_id", "created", "intents", "references": [{refer, title, content, link, media, publish_date}]}. Knobs: provider zhipu|zhihu; count 1-50 (default 10); recency oneDay|oneWeek|oneMonth|oneYear|noLimit; content_size medium|high; domain restricts to one site; engine is provider-specific (zhipu: search_std / search_pro / search_pro_sogou / search_pro_quark, default search_pro). Nothing is persisted.$txt$,
     'Live open-web search returning references without summarizing.',
     'CATALOG row — the MCP server (llm_agents/mcp/readonly_server.py) owns the live schema; this row documents it in the registry.',
     15),
    ('web_summarize',
     'mcp',
     4,
     'Tool: web_summarize (MCP)',
     1,
     $txt$Search the open web (LIVE network call, no DB), then answer the query with an LLM summary over the retrieved references. Returns {"question", "answer", "cited_refs", "references", "provider", "model", "mode", ...} — the answer carries inline [来源：ref_N] markers whose ref_N tags match the references. mode compose (default) = search, then a separate LLM pass over the references (refs cannot go missing); native = the provider's one-shot search-in-chat. lang sets the answer language (zh default); model overrides the provider's default chat model; the web_search knobs apply as there. Nothing is persisted.$txt$,
     'Live web search answered with an LLM summary over the references.',
     'CATALOG row — the MCP server (llm_agents/mcp/readonly_server.py) owns the live schema; this row documents it in the registry.',
     16),
    ('stats_ma',
     'stats',
     4,
     'Tool: stats_ma',
     1,
     $txt$Moving-average study for ONE security at the house windows — INCLUDING the 10-day short-term line the precomputed stats columns never carried (sma 5/10/20/60/120/252, ema 6/10/12/20/26/60/120/252; precomputed columns are reused when they cover the window, anything else computes from the daily bars). Per window: the MA level, the close-vs-MA spread %, its percentile rank and z-score within the security's OWN trailing 252 trading days, and a verdict (>=90th pct stretched-high — extension invites profit-taking; <=10th stretched-low — the oversold stretch snapbacks come from). Ends with the alignment verdict over the requested windows (bullish 多头排列 = close > ma(w1) > ma(w2) > …, pullbacks into the stack are the buyable zones; bearish 空头排列 reversed — rallies get sold into; else mixed). For the MATERIALIZED gap set — the 9 price-vs-MA / MA5-vs-MA pairs with their own-history trailing ranks — LOAD analysis.mov_ave_spreads_detail ⋈ analysis.mov_ave_spreads_detail_trailing (kg_search '均线 ma spread' shows the exact columns) instead of recomputing; stats_ma covers the windows and bar-level alignment the tables do not store.$txt$,
     'Moving-average study at the house windows (the 10-day line included).',
     'Schema description the model sees; tools.stats_tools.StatsMaTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     17),
    ('stats_rsi',
     'stats',
     4,
     'Tool: stats_rsi',
     1,
     $txt$Wilder RSI for ONE security (alpha = 1/window, the repo's RSI convention) at the six house windows 3/6/10/14/20/60 — the same set analysis.mov_ave_rsi stores — or your override. Zones: >70 overbought, <30 oversold — read as exhaustion/capitulation CONTEXT, not bare signals (RSI deeply oversold while the MACD histogram fades is the exhaustion-prone down-move).$txt$,
     'Wilder RSI at the six house windows.',
     'Schema description the model sees; tools.stats_tools.StatsRsiTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     18),
    ('stats_macd',
     'stats',
     4,
     'Tool: stats_macd',
     1,
     $txt$MACD(12,26,9) for ONE security: the line (EMA12 − EMA26), its signal, and the histogram with its last five values and direction — the house momentum-confirmation read: histogram sign + 5-session trend judges whether momentum CONFIRMS the latest move (hist rising with the move) or is FADING beneath it (the exhaustion caveat). The histogram's percentile rank and z-score come back against its own trailing 252 trading days. Reads the view's MATERIALIZED macd_line/macd_signal/macd_hist columns when they cover the window (stats.*_tech_stats) and computes from close only for the not-yet-backfilled tail.$txt$,
     'The classic MACD read with the histogram confirmation verdict.',
     'Schema description the model sees; tools.stats_tools.StatsMacdTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     19),
    ('stats_roc',
     'stats',
     4,
     'Tool: stats_roc',
     1,
     $txt$Momentum as n-day rate of change (%) for ONE security at the analysis anchors 5 and 20 (one trading week / one trading month — analysis.mov_ave_momentum) or your override. Each line: the ROC, its percentile rank and z-score within the security's OWN trailing 252 trading days, and the stretched/neutral verdict — momentum judged against its own history, never an absolute bar.$txt$,
     'Momentum as n-day rate of change at the analysis anchors.',
     'Schema description the model sees; tools.stats_tools.StatsRocTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     20),
    ('stats_volume',
     'stats',
     4,
     'Tool: stats_volume',
     1,
     $txt$Participation (放量/缩量) study for ONE security: 成交额 trading_amount vs its own MA{W}, and — when the exchange totals are available — the house gauge: the security's MARKET SHARE vs its own W-day MA share (analysis.mov_ave_trading_amt's trading_amt_market_share_vs_maW; W=20 is the default quote). share-vs-MA > 0 = 放量 (participation surging), < 0 = 缩量 (willingness shrinking) — share, not raw yuan, isolates the security's own participation. Also the day's amount percentile within its OWN trailing 252 days (>=0.9 天量 extreme volume, <=0.1 地量 extreme quiet). Read 量价背离: a price move the share gauge does not confirm is credibility-discounted.$txt$,
     'The 放量/缩量 participation gauge (market share vs its own MA).',
     'Schema description the model sees; tools.stats_tools.StatsVolumeTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     21),
    ('stats_range',
     'stats',
     4,
     'Tool: stats_range',
     1,
     $txt$Where price sits in ONE security's OWN trailing window (default 60/120/252 trading days — the analysis band periods): the window high/low with their dates, the close's position within that range (%: 0 = at the low, 100 = at the high), and the drawdown from the window high %. A bottom-tail range position is the oversold context snapbacks come from; a top-tail one the profit-taking zone. Note: pre-2024-10 index rows may carry synthesized O/H/L (is_ohl_estimated) — treat their highs/lows as ≈ close.$txt$,
     'Position within the security''s own trailing range, plus drawdown.',
     'Schema description the model sees; tools.stats_tools.StatsRangeTool.DEFAULT_DESCRIPTION is the built-in fallback.',
     22),
    ('load_prompt',
     'prompts',
     4,
     'Tool: load_prompt',
     1,
     $txt$Load ONE cataloged skill's full instruction text by prompt_key (a key from the [Prompt catalog] block) — call it the moment YOUR work enters that skill's domain, then apply the skill to the rest of your work. One key per call; never fetch skills wholesale.$txt$,
     'Load one cataloged skill''s instruction by key.',
     $note$The prompt-loading ladder's dynamic rung: one cataloged skill's instruction on demand (tools/prompt_tools.py). Seeded from the LoadPromptTool class.$note$,
     60),
    ('kg_search',
     'kg',
     4,
     'Tool: kg_search',
     1,
     $txt$Search a knowledge graph for WHAT a question is about — call this BEFORE db_run_query / db_list_tables or wholesale prompt fetches. namespace 0 (default) = DB semantics: the TABLES by business meaning (动量 momentum, 均线 ma, 估值 valuation pe, 融资融券 margin, 期权 implied vol, 拥挤度 crowdedness …) with their one-line meaning, trader tags, and the edges saying how they relate (computed_from = derived ← source, anchored_by = keyed on an identity table's grain, similar_to = same-concept family, joins_on = the key two tables are commonly JOINed on, (code, date) or code). namespace 1 = the prompt catalog: WHICH SKILL teaches a domain and which prompts relate — then load_prompt the skill when it is in your [Prompt catalog] block. namespace 2 = data & labels: the static.label_dim SMALLINT vocabularies (macd, mov_rsi, buy/sell, top/bottom, CALL/PUT, regime …) and WHICH tables each one types (labeled_by/for_<column> edges). OMIT namespace and BOTH 0 and 2 are searched together — the tables by meaning plus the typed-vocabulary lane that catches code-word queries plain table vocabulary misses. Results load GRADUALLY in two tiers: the default detail:'lean' renders the head of the ranking — top tables with their key columns + reading SQL templates; when that misses, re-search the SAME query with detail:'full' for every ranked node with complete column schemas (filter on the PRIMARY KEY / key columns shown — usually (code, date)); when BOTH tiers miss, STOP searching and compute in the sandbox — sandbox_write_file a script + sandbox_run it, importing study_kit first (db.fetch_daily_bars / studies.*) to load raw bars and calculate. Token matching is EXACT trader vocabulary — when the top hits miss your concept or cover only part of it, PROPOSE 2-3 SYNONYMS / paraphrases (Chinese AND English trader terms: 间距→spread→乖离, 排列→alignment, 量→volume/amount, 动量→momentum/roc) and kg_search them again BEFORE listing schemas blind with db_list_tables.$txt$,
     'Knowledge-graph traversal search: namespaces 0+2 = the tables a question is about (by meaning and by typed vocabulary), 1 = which skill teaches it.',
     $note$The schema's, the prompt catalog's and the label index's semantic index: seed match → spreading activation over llm.kg_* namespaces 0/1/2 (llm_agents/kg). Seeded from the KgSearchTool class.$note$,
     61),
    ('kg_expand',
     'kg',
     4,
     'Tool: kg_expand',
     1,
     $txt$Expand name(s) into their knowledge-graph neighborhood: every edge the node rides — for a TABLE (namespace 0): what it is computed FROM, what is computed from IT, which identity table anchors its grain, its same-concept family, plus its exact column names + comments loaded from the DB and the PRIMARY KEY + index grain; for a PROMPT (namespace 1): which prompts teach the same domain and which are alternate picks; for a LABEL DOMAIN (namespace 2): every table a SMALLINT vocabulary types and which column carries it. Use after kg_search to drill into a hit, or when you already know a name and need what feeds it / what it feeds.$txt$,
     'One name''s knowledge-graph neighborhood (feeders, derivations, family, alternates, typed tables).',
     $note$The drill-down face of the same graphs (llm_agents/kg). Seeded from the KgExpandTool class.$note$,
     62),
    ('ad_hoc_llm_request',
     'ad_hoc',
     4,
     'Tool: ad_hoc_llm_request',
     1,
     $txt$Make ONE independent LLM request over a FRESH minimal context — for a self-contained side question that does not need your conversation (classify this list, summarize this one document, reformat this passage). NOTHING of your context is carried: put everything the request needs INTO prompt (quote the facts or text verbatim); keep the ask narrow and the expected answer compact. SPLIT RULE: whenever a sub-task does not need your carried context, split it OUT of your own work and send it here as a fresh-context request instead of doing it inline — each such request carries only its own small prompt, so this conversation stays lean; several independent sub-tasks become several separate requests. Do NOT use it for anything needing your tools, the run's data, or multi-turn back-and-forth.$txt$,
     'One independent fresh-context LLM request; nothing of this conversation is carried.',
     $note$The cheap middle between the conversation and a spawn: a standalone two-message request over the run's provider (llm_agents/deep_agents/ad_hoc_llm_request.py), logged as its own one-row request chain. Seeded from the AdHocRequestTool class.$note$,
     63),
    ('fork_subagent',
     'delegation',
     4,
     'Tool: fork_subagent',
     1,
     $txt$Fork this conversation: a subagent node CONTINUES from the full context above (every message, tool result and script already in play — unlike spawn_subagent, whose subagent sees ONLY the goal you write) and works the objective you give, starting from where this conversation stands. The forked node's final answer comes back as this tool's result and this conversation stays on its own thread. Use fork_subagent when the next work chunk needs everything discussed so far but would burn this node's own step budget or derail its main line — the fork inherits the context so nothing is re-derived; use spawn_subagent when a fresh, self-contained sub-question is enough. The fork runs in the FOREGROUND — this call returns only when the forked node hands back — and the forked node may itself spawn or fork further subagents below the depth cap. It shares this sandbox session (its files and scripts are already visible to it).$txt$,
     'Fork this conversation — the forked node inherits the full context and continues it.',
     $note$Schema description the model sees; tools.delegation_tools.ForkSubagentTool.DEFAULT_DESCRIPTION is the built-in fallback.$note$,
     64)

ON CONFLICT (prompt_key, prompt_sub_type) DO UPDATE
    SET prompt_type = EXCLUDED.prompt_type,
        title       = EXCLUDED.title,
        instruction = EXCLUDED.instruction,
        preview     = EXCLUDED.preview,
        note        = EXCLUDED.note,
        ordinal     = EXCLUDED.ordinal,
        is_active   = true,
        updated_at  = now();
